_PATTERN = re.compile(r'^(?:(\d+)d)?(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$')


def parse_duration(s):
    """Parse a duration string into an integer number of seconds.

    The string may have surrounding whitespace. Its body must be one or
    more non-negative integer amounts followed by a unit, in the order
    d, h, m, s. Each unit may appear at most once.
    """
    if not isinstance(s, str):
        raise ValueError('duration must be a string')

    s = s.strip()
    if not s:
        raise ValueError('empty duration')

    match = _PATTERN.fullmatch(s)
    if match is None:
        raise ValueError(f'invalid duration: {s!r}')

    days, hours, minutes, seconds = match.groups()
    if days is None and hours is None and minutes is None and seconds is None:
        raise ValueError(f'invalid duration: {s!r}')

    total = 0
    if days is not None:
        total += int(days) * 86400
    if hours is not None:
        total += int(hours) * 3600
    if minutes is not None:
        total += int(minutes) * 60
    if seconds is not None:
        total += int(seconds)

    return total
